    "code": "import numpy as np\n\ndef look_at(C, target, up=(0, 0, 1)):\n    C = np.asarray(C, float)\n    z = np.asarray(target, float) - C\n    z /= np.linalg.norm(z)\n    x = np.cross(z, up)\n    x /= np.linalg.norm(x)\n    y = np.cross(z, x)\n    R = np.vstack([x, y, z])\n    t = -R @ C\n    return R, t\n\ndef project(K, R, t, Pw):\n    Pc = (R @ np.asarray(Pw, float).T).T + t\n    p = (K @ Pc.T).T\n    return p[:, :2] / p[:, 2:3], Pc[:, 2]\n\nK = np.array([[1000, 0, 640], [0, 1000, 360], [0, 0, 1.0]])\nR, t = look_at([0, -10, 3], [0, 0, 0])\nPw = np.array([[0, 0, 0], [1, 0, 0], [0, 1, 0], [0, 0, 1], [2, 3, 0]], float)\nuv, depth = project(K, R, t, Pw)\n",
