    "code": "import numpy as np\nimport cv2\n\ndef pixel_to_ground(uv, K, dist, R, C, ground_z=0.0):\n    und = cv2.undistortPoints(np.asarray(uv, np.float64).reshape(-1, 1, 2), K, dist).reshape(-1, 2)\n    rays_cam = np.c_[und, np.ones(len(und))]\n    rays_w = rays_cam @ R\n    s = (ground_z - C[2]) / rays_w[:, 2]\n    P = C + s[:, None] * rays_w\n    P[s <= 0] = np.nan\n    return P\n",
