    "code": "def R_from_attitude(yaw_deg, pitch_deg, roll_deg=0.0):\n    y, p, r = np.radians([yaw_deg, pitch_deg, roll_deg])\n    fwd = np.array([np.sin(y) * np.cos(p), np.cos(y) * np.cos(p), np.sin(p)])\n    right = np.array([np.cos(y), -np.sin(y), 0.0])\n    down = np.cross(fwd, right)\n    Rc = np.vstack([right, down, fwd])\n    cr, sr = np.cos(r), np.sin(r)\n    return np.array([[cr, -sr, 0], [sr, cr, 0], [0, 0, 1]]) @ Rc\n",
