    "code": "# ---- 1. the vanishing point of the lane lines -> the horizon row\ndef fit_line(pts):\n    \"\"\"a line a*x + b*y = c through noisy points (total least squares)\"\"\"\n    m = pts.mean(axis=0)\n    _, _, Vt = np.linalg.svd(pts - m)\n    a, b = Vt[-1]                       # the normal: the direction of least spread\n    return np.array([a, b, a * m[0] + b * m[1]])\n\nL3 = np.array([fit_line(p) for p in lines_px])\nv = np.linalg.lstsq(L3[:, :2], L3[:, 2], rcond=None)[0]   # the point closest to all lines\n\n# ---- 2. for every candidate f: pitch from the horizon, then the cars' shape on the ground\ndef ground(uv, K, R):\n    \"\"\"pixel -> ground, for a camera at height 1 (so the result is in units of the unknown height)\"\"\"\n    rays = np.c_[np.asarray(uv, float), np.ones(len(uv))] @ np.linalg.inv(K).T @ R\n    return rays[:, :2] * (-1.0 / rays[:, 2:3])\n\ndef setup(f):\n    pitch = np.degrees(np.arctan2(H / 2 - v[1], f))     # horizon row = cy - f*tan(pitch)\n    return camera(f, pitch, 0.0), pitch                 # yaw 0: the ground map comes out rotated, which changes no length\n\ndef car_ratio(f):\n    (K, R), _ = setup(f)\n    ratios = []\n    for c in cars_px:\n        g = ground(c, K, R)\n        length = np.linalg.norm(g[0] - g[3]) + np.linalg.norm(g[1] - g[2])\n        width = np.linalg.norm(g[0] - g[1]) + np.linalg.norm(g[3] - g[2])\n        ratios.append(length / width)\n    return np.median(ratios)\n\nfs = np.arange(400, 3001, 10.0)\nr = np.array([car_ratio(f) for f in fs])\nf_est = fs[np.argmin(np.abs(r - 2.5))]          # a typical car: 4.5 m long, 1.8 m wide\n(K, R), pitch_est = setup(f_est)\n\n",
